#[error_code]
pub enum GenError {
	Math,
	Empty,
	Paused,
	Limit,
	Claimed,
	SameAccount,
	BadConfig,
	NoDest,
	BadDest,
	AlreadyInitialized,
	NotOpen,
	BadIx,
	BadRepay,
	BadOracle,
	Stale,
}
